# Pasadizo, north hut (the underground passage between Ruta 5 and Ruta 6, C3, contract 34), 8 x 7, interior. column = i, row = j. The path keeper's hut: crates and barrels, a table with a
# lamp, a bench, the ladder down to the passage (a floor hatch, the door L) and the door mat to Ruta 5.
@map pasadizo_n
@size 8 7
@interior yes
@bg 3
@fill floor_wood
@spawn door 3 5 N
@spawn ladder 2 2 S             # arriving from the passage
@legend
  .  tile=floor_wood
  C  tile=none object=wall_corner
  w  tile=none object=wall_j
  y  tile=none object=wall_win_j
  |  tile=none object=wall_i
  q  tile=none object=wall_win_i
  H  object=crate_plain
  x  object=barrel
  T  object=table
  l  object=lamp
  L  tile=floor_wood door=rope_ladder
  G  npc=guardia id=keeper face=N text=pasadizo.keeper.n
  B  object=bench
  m  tile=mat
@grid
  Cwwwwyww
  |.Ll..HH
  |..T...x
  q....G..
  |.......
  |B......
  |..mm...
@warp m -> ruta_5 spawn=hut_door
@warp L -> pasadizo spawn=north
